{
  "lesson_summary": "Today's lesson plans to teach children to count groups of objects up to 9, and then to read and write each number as a numeral and as a word. The lesson uses examples like counting two raised fingers and writing the number 6 in words.",
  "lesson_summary_short": "Today's lesson plans to teach children to count numbers from 0 to 9 using examples like two raised fingers.",
  "checks_summary": "This quiz checks whether the class can count objects, identify numerals, and write number words for numbers up to 9.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "How many fingers are shown?",
      "options": [
        "2",
        "1",
        "3"
      ],
      "correct_index": 0,
      "explanation": "The picture shows two fingers. Counting them one by one gives 'one, two'.",
      "selected_because": "The lesson started with counting two raised fingers.",
      "distractor_misconceptions": {
        "1": "Confuses the count with the first finger only.",
        "2": "Counts one more than shown."
      },
      "option_feedback": {
        "correct": "Yes, there are two fingers shown. The lesson taught to count each finger one by one.",
        "wrong": {
          "1": "This shows only one finger. Remember to count every finger you see. There are two fingers shown.",
          "2": "This is one more than the fingers shown. Count each finger carefully. There are two fingers shown."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "finger",
        "count": 2
      },
      "figure_role": "count_compare",
      "source_quote": "Two raised fingers: one, two. The last count word is two — write 2",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which numeral is 'two'?",
      "options": [
        "2",
        "1",
        "3"
      ],
      "correct_index": 0,
      "explanation": "The numeral '2' represents the quantity 'two'.",
      "selected_because": "The lesson explicitly linked the count 'two' to the numeral '2'.",
      "distractor_misconceptions": {
        "1": "Confuses 'two' with 'one'.",
        "2": "Confuses 'two' with 'three'."
      },
      "option_feedback": {
        "correct": "That's right! The numeral '2' is how we write the number 'two'.",
        "wrong": {
          "1": "This is the numeral for 'one'. The numeral for 'two' looks different. The numeral for 'two' is '2'.",
          "2": "This is the numeral for 'three'. The numeral for 'two' is '2'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "The last count word is two — write 2",
      "teaching_error": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which word is for the numeral 6?",
      "options": [
        "six",
        "five",
        "seven"
      ],
      "correct_index": 0,
      "explanation": "The word 'six' represents the numeral '6'.",
      "selected_because": "The lesson practiced writing the number 6 in words.",
      "distractor_misconceptions": {
        "1": "Confuses 'six' with 'five' due to similar sounds.",
        "2": "Confuses 'six' with 'seven'."
      },
      "option_feedback": {
        "correct": "Correct! The word 'six' is how we write the numeral 6.",
        "wrong": {
          "1": "This word is 'five'. Remember, the numeral 6 is written as 'six'.",
          "2": "This word is 'seven'. The numeral 6 is written as 'six'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Write the number 6 in words.",
      "teaching_error": {
        "said": "Children write 'five' for numeral 6 — the word and the numeral shape get mixed up.",
        "correct": "The word 'six' represents the numeral '6'."
      }
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which numeral is for 'four'?",
      "options": [
        "4",
        "5",
        "3"
      ],
      "correct_index": 0,
      "explanation": "The numeral '4' represents the number word 'four'.",
      "selected_because": "The lesson practiced writing the number word 'four' in numerals.",
      "distractor_misconceptions": {
        "1": "Confuses 'four' with 'five'.",
        "2": "Confuses 'four' with 'three'."
      },
      "option_feedback": {
        "correct": "You got it! The numeral '4' is how we write the word 'four'.",
        "wrong": {
          "1": "This is the numeral for 'five'. The numeral for 'four' is '4'.",
          "2": "This is the numeral for 'three'. The numeral for 'four' is '4'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Write the number word four in numerals.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many butterflies are there?",
      "options": [
        "7",
        "6",
        "8"
      ],
      "correct_index": 0,
      "explanation": "Counting each butterfly in the picture gives a total of seven.",
      "selected_because": "The lesson used a picture of butterflies to practice counting.",
      "distractor_misconceptions": {
        "1": "Miscounts by one less.",
        "2": "Miscounts by one more."
      },
      "option_feedback": {
        "correct": "That's right! There are seven butterflies in the picture.",
        "wrong": {
          "1": "Look closely and count again. There is one more butterfly than you counted. There are seven butterflies.",
          "2": "You counted one too many. Count each butterfly carefully. There are seven butterflies."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "butterfly",
        "count": 7
      },
      "figure_role": "count_compare",
      "source_quote": "Count the butterflies and write the numeral in the box.",
      "teaching_error": null
    },
    {
      "slo_id": "S4",
      "level": "understand",
      "question": "What number does '2' read as?",
      "options": [
        "two",
        "one",
        "three"
      ],
      "correct_index": 0,
      "explanation": "The numeral '2' is read as the word 'two'.",
      "selected_because": "The lesson included reading numbers up to 9 in numerals.",
      "distractor_misconceptions": {
        "1": "Confuses the reading of '2' with 'one'.",
        "2": "Confuses the reading of '2' with 'three'."
      },
      "option_feedback": {
        "correct": "Correct! The numeral '2' is read as 'two'.",
        "wrong": {
          "1": "The numeral '1' is read as 'one'. The numeral '2' is read as 'two'.",
          "2": "The numeral '3' is read as 'three'. The numeral '2' is read as 'two'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Read your writing back aloud to check numeral and word say the same name.",
      "teaching_error": null
    },
    {
      "slo_id": "S5",
      "level": "understand",
      "question": "What numeral is 'zero'?",
      "options": [
        "0",
        "1",
        "2"
      ],
      "correct_index": 0,
      "explanation": "The word 'zero' is represented by the numeral '0'.",
      "selected_because": "The lesson covered counting and writing numbers from 0 to 9.",
      "distractor_misconceptions": {
        "1": "Confuses 'zero' with 'one'.",
        "2": "Confuses 'zero' with 'two'."
      },
      "option_feedback": {
        "correct": "That's right! The numeral '0' means 'zero'.",
        "wrong": {
          "1": "This is the numeral for 'one'. The numeral for 'zero' is '0'.",
          "2": "This is the numeral for 'two'. The numeral for 'zero' is '0'."
        }
      },
      "figure": {
        "type": "count_frame",
        "count": 0
      },
      "figure_role": "model",
      "source_quote": "I can count numbers from 0 to 9.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many counters are there?",
      "options": [
        "5",
        "4",
        "6"
      ],
      "correct_index": 0,
      "explanation": "There are five counters shown in the picture.",
      "selected_because": "The lesson used counters for counting practice.",
      "distractor_misconceptions": {
        "1": "Miscounts by one less.",
        "2": "Miscounts by one more."
      },
      "option_feedback": {
        "correct": "Excellent! There are five counters.",
        "wrong": {
          "1": "You missed one counter. Count them all carefully. There are five counters.",
          "2": "You counted one too many. Please count again. There are five counters."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 5
      },
      "figure_role": "count_compare",
      "source_quote": "A picture group, its numeral and its number word all show the same amount.",
      "teaching_error": null
    }
  ]
}
